BEGIN;
-- =====================================================================================
-- Kornpassorn Care — 01 โครงสร้างตาราง
-- สร้างโดย backend/scripts/build-db-setup.ts เมื่อ 2026-10-17 (อย่าแก้มือ — รันสคริปต์ใหม่แทน)
-- รันกับฐานข้อมูลว่าง — สร้างตารางทั้งหมดที่แอปใช้
-- =====================================================================================

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

CREATE TABLE "users" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "username" character varying(100) NOT NULL, "password_hash" character varying NOT NULL, "email" character varying, "first_name" character varying(100), "last_name" character varying(100), "phone_number" character varying(20), "isActive" boolean NOT NULL DEFAULT true, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "role" character varying NOT NULL DEFAULT 'user', CONSTRAINT "PK_a3ffb1c0c8416b9fc6f907b7433" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "IDX_fe0bb3f6520ee0469504521e71" ON "users" ("username");
CREATE TABLE "patients" ("id" SERIAL NOT NULL, "patient_code" character varying(20) NOT NULL, "first_name" character varying(100) NOT NULL, "last_name" character varying(100) NOT NULL, "gender" character varying(10), "date_of_birth" date, "phone" character varying(20), "national_id" character varying(13), "email" character varying(100), "address" text, "blood_type" character varying(5), "is_active" boolean NOT NULL DEFAULT true, "created_at" TIMESTAMP NOT NULL DEFAULT now(), "updated_at" TIMESTAMP NOT NULL DEFAULT now(), CONSTRAINT "UQ_72398f0b54d401540321d5db8bf" UNIQUE ("patient_code"), CONSTRAINT "PK_a7f0b9fcbb3469d5ec0b0aceaa7" PRIMARY KEY ("id"));
CREATE TABLE "medical_records" ("id" SERIAL NOT NULL, "patient_id" integer NOT NULL, "visit_date" TIMESTAMP NOT NULL, "symptoms" text, "diagnosis" text, "treatment" text, "doctor_name" character varying(100), "note" text, "created_at" TIMESTAMP NOT NULL DEFAULT now(), CONSTRAINT "PK_c200c0b76638124b7ed51424823" PRIMARY KEY ("id"));
CREATE TABLE "user_tokens" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "token_hash" character varying, "jti" uuid, "token_type" character varying NOT NULL DEFAULT 'access', "device_info" jsonb, "device_ip" inet, "revoked_by" uuid, "revoked_at" TIMESTAMP, "revoked_reason" text, "created_at" TIMESTAMP NOT NULL DEFAULT now(), "expired_at" TIMESTAMP, "last_used" TIMESTAMP, "is_permanent" boolean NOT NULL DEFAULT false, "revoked" boolean NOT NULL DEFAULT false, "userId" uuid, "patientId" integer, CONSTRAINT "PK_63764db9d9aaa4af33e07b2f4bf" PRIMARY KEY ("id"));
CREATE INDEX "IDX_92ce9a299624e4c4ffd99b645b" ON "user_tokens" ("userId");
CREATE INDEX "IDX_3ebaa4fed92ebcadb7e7eef82c" ON "user_tokens" ("patientId");
CREATE INDEX "IDX_ebdd918653813b59cdd5d379b5" ON "user_tokens" ("token_hash");
CREATE UNIQUE INDEX "IDX_cf8bff5dc33a46985bf6b2071e" ON "user_tokens" ("jti");
CREATE INDEX "IDX_2564686b1784629fad8769b54f" ON "user_tokens" ("expired_at");
CREATE INDEX "IDX_077c7728aeb1dec1b6cce972d1" ON "user_tokens" ("revoked");
CREATE TABLE "login_logs" ("id" SERIAL NOT NULL, "login_time" TIMESTAMP NOT NULL DEFAULT now(), "ip_address" character varying(45), "user_agent" text, "success" boolean NOT NULL DEFAULT false, "fail_reason" text, "user_id" uuid, "patient_id" integer, CONSTRAINT "PK_15f7b02ad55d5ba905b2962ebab" PRIMARY KEY ("id"));
CREATE TABLE "inventory_products" ("id" SERIAL NOT NULL, "sku" character varying(50), "name" character varying(255) NOT NULL, "category" character varying(30) NOT NULL DEFAULT 'other', "generic_name" character varying(150), "strength" character varying(50), "dosage_form" character varying(30), "unit" character varying(30), "sell_price" numeric(12,2), "reorder_level" numeric(12,2), "description" text, "is_active" boolean NOT NULL DEFAULT true, "create_by" character varying(50) NOT NULL DEFAULT 'system', "create_date" TIMESTAMP NOT NULL DEFAULT now(), "modify_by" character varying(50), "modify_date" TIMESTAMP DEFAULT now(), CONSTRAINT "UQ_ce1be0c7a9500f1f0d6ba34ed1c" UNIQUE ("sku"), CONSTRAINT "PK_f0025e3643d268bfda5f6cf9028" PRIMARY KEY ("id"));
CREATE TABLE "inventory_product_packages" ("id" SERIAL NOT NULL, "product_id" integer NOT NULL, "brand" character varying(100) NOT NULL, "pack_unit" character varying(30) NOT NULL, "pack_size" integer NOT NULL, "barcode" character varying(50), "description" character varying(255), "note" character varying(255), "last_pack_cost" numeric(12,2), "is_default" boolean NOT NULL DEFAULT false, "is_active" boolean NOT NULL DEFAULT true, "create_by" character varying(50) NOT NULL DEFAULT 'system', "create_date" TIMESTAMP NOT NULL DEFAULT now(), "modify_by" character varying(50), "modify_date" TIMESTAMP, CONSTRAINT "PK_abd1f8740c1f655b55f39c15964" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "IDX_6f1d7b6caff20c552fde31f738" ON "inventory_product_packages" ("product_id", "brand", "pack_unit", "pack_size");
CREATE TABLE "inventory_product_lots" ("id" SERIAL NOT NULL, "product_id" integer NOT NULL, "lot_no" character varying(50) NOT NULL, "manufacture_date" date, "expiry_date" date, "package_id" integer, "pack_unit" character varying(30), "pack_size" integer, "quantity_in" numeric(12,2) NOT NULL, "received_pack_qty" numeric(12,2), "quantity_remaining" numeric(12,2) NOT NULL, "unit_cost" numeric(12,2), "supplier" character varying(100), "brand" character varying(100), "received_date" date NOT NULL DEFAULT ('now'::text)::date, "note" character varying(255), "create_by" character varying(50) NOT NULL DEFAULT 'system', "create_date" TIMESTAMP NOT NULL DEFAULT now(), "modify_by" character varying(50), "modify_date" TIMESTAMP, CONSTRAINT "PK_d81d769e6b9a8ef4b4156ebd58a" PRIMARY KEY ("id"));
CREATE INDEX "IDX_b53681ae032d7fba29ea517a6c" ON "inventory_product_lots" ("expiry_date");
CREATE UNIQUE INDEX "IDX_d4082bfd4a0c65c7d84f01eff6" ON "inventory_product_lots" ("product_id", "lot_no");
CREATE TABLE "inventory_stock_movements" ("id" SERIAL NOT NULL, "product_lot_id" integer NOT NULL, "movement_type" character varying(10) NOT NULL, "quantity" numeric(12,2) NOT NULL, "document_item_id" integer, "moved_date" TIMESTAMP NOT NULL DEFAULT now(), "note" character varying(255), CONSTRAINT "PK_798fae89496e9e99ce4614b7101" PRIMARY KEY ("id"));
CREATE INDEX "IDX_6f4cec8b2fb2403faa9965c76b" ON "inventory_stock_movements" ("document_item_id");
CREATE TABLE "document_sequences" ("id" SERIAL NOT NULL, "doc_prefix" character varying(5) NOT NULL, "doc_year" integer NOT NULL, "last_number" integer NOT NULL DEFAULT '0', CONSTRAINT "PK_be5517d83b0425544ef91e6c897" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "IDX_cbeb79e7d59895cd14895a5b15" ON "document_sequences" ("doc_prefix", "doc_year");
CREATE TABLE "documents" ("id" SERIAL NOT NULL, "doc_no" character varying(30) NOT NULL, "doc_type" character varying(20) NOT NULL, "doc_date" date NOT NULL, "status" character varying(20) NOT NULL DEFAULT 'confirmed', "total_amount" numeric(12,2) NOT NULL DEFAULT '0', "supplier" character varying(150), "reason" character varying(150), "note" character varying(500), "patient_id" integer, "void_reason" character varying(255), "void_by" character varying(50), "void_date" TIMESTAMP, "create_by" character varying(50) NOT NULL DEFAULT 'system', "create_date" TIMESTAMP NOT NULL DEFAULT now(), CONSTRAINT "UQ_6ef8ce4b8ca8d1232f7fdd18e4a" UNIQUE ("doc_no"), CONSTRAINT "PK_ac51aa5181ee2036f5ca482857c" PRIMARY KEY ("id"));
CREATE INDEX "IDX_7e4100684aed688061ba9eb0b6" ON "documents" ("doc_type");
CREATE INDEX "IDX_397dd7c320718aecc64ee34f79" ON "documents" ("doc_date");
CREATE TABLE "document_items" ("id" SERIAL NOT NULL, "document_id" integer NOT NULL, "line_no" integer NOT NULL, "item_type" character varying(20) NOT NULL DEFAULT 'product', "direction" character varying(5), "category" character varying(100), "product_id" integer, "product_lot_id" integer, "package_id" integer, "pack_qty" numeric(12,2), "quantity" numeric(12,2), "unit_price" numeric(12,2), "amount" numeric(12,2) NOT NULL DEFAULT '0', "description" character varying(500), CONSTRAINT "PK_09473d260190ca635dbe2bc5a98" PRIMARY KEY ("id"));
CREATE TABLE "finance_records" ("id" SERIAL NOT NULL, "item_name" character varying(255) NOT NULL, "category" character varying(20) NOT NULL, "amount" numeric(12,2) NOT NULL, "record_date" date NOT NULL, "description" character varying(500), "document_id" integer, "create_by" character varying(50) DEFAULT 'system', "create_date" TIMESTAMP NOT NULL DEFAULT now(), "modify_by" character varying(50), "modify_date" TIMESTAMP DEFAULT now(), CONSTRAINT "PK_fa96ad926c6fef153a00736aeab" PRIMARY KEY ("id"));
CREATE INDEX "IDX_d6a64b3325c2912a31583f35c3" ON "finance_records" ("document_id");
CREATE TABLE "patient_otps" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "phone" character varying(20) NOT NULL, "otp_hash" character varying NOT NULL, "attempts" integer NOT NULL DEFAULT '0', "consumed_at" TIMESTAMP, "expires_at" TIMESTAMP NOT NULL, "created_at" TIMESTAMP NOT NULL DEFAULT now(), CONSTRAINT "PK_2bdd6dab8c6373451e3d7e4a974" PRIMARY KEY ("id"));
CREATE INDEX "IDX_a4261208bcf30b2cd9cab8e146" ON "patient_otps" ("phone");
CREATE TABLE "questionnaire_question" ("id" SERIAL NOT NULL, "code" character varying(64) NOT NULL, "text" text NOT NULL, "type" character varying(32) NOT NULL, "choices" text array, "is_required" boolean NOT NULL DEFAULT false, CONSTRAINT "UQ_9c9a79c090606c2dc0887a07a09" UNIQUE ("code"), CONSTRAINT "PK_eae0e95bd5a0ba7fe0fc1e3470b" PRIMARY KEY ("id"));
CREATE TABLE "patient_questionnaire" ("id" SERIAL NOT NULL, "patient_id" integer, "guest_first_name" character varying(100), "guest_last_name" character varying(100), "created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updated_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "status" character varying(32) NOT NULL DEFAULT 'draft', "note" text, CONSTRAINT "PK_c955c53432741738f92ad3e1eec" PRIMARY KEY ("id"));
CREATE TABLE "patient_questionnaire_answer" ("id" SERIAL NOT NULL, "questionnaire_id" integer NOT NULL, "question_id" integer NOT NULL, "answer_text" text, "answered_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "PK_df7a32a71abcff7d670cfdc5d03" PRIMARY KEY ("id"));
CREATE TABLE "hospital_weekly_hours" ("id" SERIAL NOT NULL, "day_of_week" smallint NOT NULL, "is_closed" boolean NOT NULL DEFAULT false, "open_time" TIME, "close_time" TIME, "note" character varying(255), "updated_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "PK_25b88f6837031ebf18760c11b5e" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "IDX_6592d2a247d6d71174094cb1b8" ON "hospital_weekly_hours" ("day_of_week");
CREATE TABLE "hospital_special_days" ("id" SERIAL NOT NULL, "date" date NOT NULL, "is_closed" boolean NOT NULL DEFAULT true, "open_time" TIME, "close_time" TIME, "note" character varying(255), "created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "PK_9220f7f20107fea4973db60ec87" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "IDX_c0a9268cbd1fbc1ce9c2a49ec6" ON "hospital_special_days" ("date");
CREATE TABLE "appointments" ("id" SERIAL NOT NULL, "patient_id" integer NOT NULL, "appointment_date" date NOT NULL, "start_time" TIME NOT NULL, "end_time" TIME, "service" character varying(100) NOT NULL, "status" character varying(20) NOT NULL DEFAULT 'scheduled', "note" character varying(500), "create_by" character varying(50) NOT NULL DEFAULT 'system', "create_date" TIMESTAMP NOT NULL DEFAULT now(), "modify_by" character varying(50), "modify_date" TIMESTAMP, CONSTRAINT "PK_4a437a9a27e948726b8bb3e36ad" PRIMARY KEY ("id"));
CREATE INDEX "IDX_3330f054416745deaa2cc13070" ON "appointments" ("patient_id");
CREATE INDEX "IDX_11f259627a933ccd965d9caf9b" ON "appointments" ("appointment_date", "start_time");
